    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    if len(pts) < 3:
        hull = pts
    else:
        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        hull = lower[:-1] + upper[:-1]

    out = [row[:] for row in grid]
    if len(hull) >= 3:
        for r in range(h):
            for c in range(w):
                signs = [cross(hull[i], hull[(i + 1) % len(hull)], (c, r))
                         for i in range(len(hull))]
                if all(x >= 0 for x in signs) or all(x <= 0 for x in signs):
                    if grid[r][c] != fg:
                        out[r][c] = 3
    elif len(hull) == 2:
        # A degenerate hull has no area to fill.
        pass
    return out
