    bg = grid[0][0]
    fg = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]

    # Connect foreground cells that share a row.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == fg]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3

    # Connect foreground cells that share a column.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3

    return out
